        });
        AddRecipe(new Recipe
        {
            Title = "Caesar Salad",
            Category = "Salads",
            Description = "A crisp romaine salad with creamy Caesar dressing and croutons.",
            Ingredients = new() { "1 head romaine lettuce", "½ cup Caesar dressing", "¼ cup Parmesan cheese", "1 cup croutons", "1 lemon" },
            Steps = new() { "Wash and chop romaine lettuce.", "Toss with Caesar dressing.", "Top with Parmesan cheese and croutons.", "Squeeze lemon juice over the top and serve." }
        });
        AddRecipe(new Recipe
        {
            Title = "Spaghetti Bolognese",
            Category = "Main Courses",
            Description = "A rich and hearty Italian meat sauce over spaghetti.",
            Ingredients = new() { "400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper" },
            Steps = new() { "Cook spaghetti according to package directions.", "Brown ground beef in a large pan; drain fat.", "Add onion and garlic; cook until soft.", "Stir in tomatoes, tomato paste, and oregano. Simmer 20 minutes.", "Serve sauce over spaghetti." }
        });
        AddRecipe(new Recipe
        {
            Title = "Chocolate Chip Cookies",
            Category = "Desserts",
            Description = "Chewy chocolate chip cookies with a golden edge.",
            Ingredients = new() { "2¼ cups flour", "1 tsp baking soda", "1 tsp salt", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "2 tsp vanilla", "2 cups chocolate chips" },
