        });
        AddRecipe(new Recipe
        {
            Title = "Tomato Soup",
            Category = "Soups",
            Description = "A smooth, comforting tomato soup.",
            Ingredients = new() { "800g canned tomatoes", "1 onion, chopped", "2 cloves garlic", "2 cups vegetable broth", "2 tbsp olive oil", "Salt, pepper, basil" },
            Steps = new() { "Sauté onion and garlic in olive oil.", "Add tomatoes and broth; simmer 20 minutes.", "Blend until smooth.", "Season with salt, pepper, and basil." }
        });
        AddRecipe(new Recipe
        {
            Title = "Veggie Stir Fry",
            Category = "Main Courses",
            Description = "A quick and colorful vegetable stir fry with soy sauce.",
            Ingredients = new() { "2 cups mixed vegetables (bell peppers, broccoli, snap peas, carrots)", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 clove garlic, minced", "1 tsp ginger, grated", "Cooked rice for serving" },
            Steps = new() { "Heat sesame oil in a wok over high heat.", "Add garlic and ginger; stir 30 seconds.", "Add vegetables and stir fry 5–7 minutes.", "Add soy sauce, toss to coat.", "Serve over cooked rice." }
        });
    }

    public List<string> GetCategories() => _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
