namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public List<int> Ratings { get; set; } = new();
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new();
    private int _nextId = 1;

    public RecipeService()
    {
        // Seed data
        AddRecipe(new Recipe
        {
            Title = "Classic Pancakes",
            Category = "Breakfast",
            Description = "Fluffy homemade pancakes perfect for weekend mornings.",
            Ingredients = new() { "1½ cups flour", "3½ tsp baking powder", "1 tbsp sugar", "1¼ cups milk", "1 egg", "3 tbsp melted butter" },
            Steps = new() { "Mix dry ingredients in a bowl.", "Make a well and pour in milk, egg, and butter; mix until smooth.", "Heat a griddle over medium-high heat and pour batter.", "Cook until bubbles form, then flip and cook until golden." }
        });
        AddRecipe(new Recipe
        {
            Title = "Caesar Salad",
            Category = "Salads",
            Description = "A crisp romaine salad with creamy Caesar dressing and croutons.",
            Ingredients = new() { "1 head romaine lettuce", "½ cup Caesar dressing", "¼ cup Parmesan cheese", "1 cup croutons", "1 lemon" },
            Steps = new() { "Wash and chop romaine lettuce.", "Toss with Caesar dressing.", "Top with Parmesan cheese and croutons.", "Squeeze lemon juice over the top and serve." }
        });
        AddRecipe(new Recipe
        {
            Title = "Spaghetti Bolognese",
            Category = "Main Courses",
            Description = "A rich and hearty Italian meat sauce over spaghetti.",
            Ingredients = new() { "400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper" },
            Steps = new() { "Cook spaghetti according to package directions.", "Brown ground beef in a large pan; drain fat.", "Add onion and garlic; cook until soft.", "Stir in tomatoes, tomato paste, and oregano. Simmer 20 minutes.", "Serve sauce over spaghetti." }
        });
        AddRecipe(new Recipe
        {
            Title = "Chocolate Chip Cookies",
            Category = "Desserts",
            Description = "Chewy chocolate chip cookies with a golden edge.",
            Ingredients = new() { "2¼ cups flour", "1 tsp baking soda", "1 tsp salt", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "2 tsp vanilla", "2 cups chocolate chips" },
            Steps = new() { "Preheat oven to 375°F (190°C).", "Mix flour, baking soda, and salt.", "Beat butter and sugars until creamy; add eggs and vanilla.", "Gradually blend in flour mixture; stir in chocolate chips.", "Drop rounded tablespoons onto baking sheets.", "Bake 9–11 minutes or until golden brown." }
        });
        AddRecipe(new Recipe
        {
            Title = "Tomato Soup",
            Category = "Soups",
            Description = "A smooth, comforting tomato soup.",
            Ingredients = new() { "800g canned tomatoes", "1 onion, chopped", "2 cloves garlic", "2 cups vegetable broth", "2 tbsp olive oil", "Salt, pepper, basil" },
            Steps = new() { "Sauté onion and garlic in olive oil.", "Add tomatoes and broth; simmer 20 minutes.", "Blend until smooth.", "Season with salt, pepper, and basil." }
        });
        AddRecipe(new Recipe
        {
            Title = "Veggie Stir Fry",
            Category = "Main Courses",
            Description = "A quick and colorful vegetable stir fry with soy sauce.",
            Ingredients = new() { "2 cups mixed vegetables (bell peppers, broccoli, snap peas, carrots)", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 clove garlic, minced", "1 tsp ginger, grated", "Cooked rice for serving" },
            Steps = new() { "Heat sesame oil in a wok over high heat.", "Add garlic and ginger; stir 30 seconds.", "Add vegetables and stir fry 5–7 minutes.", "Add soy sauce, toss to coat.", "Serve over cooked rice." }
        });
    }

    public List<string> GetCategories() => _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe != null && rating >= 1 && rating <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }
}

