### 7. Create `Components/StarRating.razor` (INTERACTIVE — uses @rendermode InteractiveServer)
```razor
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <div class="star-rating" style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => SubmitRating(star)"
                  @onmouseover="() => hoverRating = star"
                  @onmouseout="() => hoverRating = 0"
                  style="color: @(GetStarColor(star))">
                @(star <= GetDisplayRating() ? "★" : "☆")
            </span>
        }
    </div>

    @if (submitted)
    {
        <span class="text-success">Thanks for rating!</span>
    }

    @{
        var recipe = RecipeService.GetById(RecipeId);
    }
    @if (recipe != null && recipe.AverageRating > 0)
    {
        <span class="text-muted ms-2">
            @recipe.AverageRating.ToString("F1") avg (@recipe.Ratings.Count ratings)
        </span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoverRating;
    private int selectedRating;
    private bool submitted;

    private int GetDisplayRating() => hoverRating > 0 ? hoverRating : selectedRating;

    private string GetStarColor(int star)
    {
        if (hoverRating > 0)
            return star <= hoverRating ? "#ffc107" : "#e0e0e0";
        return star <= selectedRating ? "#ffc107" : "#e0e0e0";
    }

    private void SubmitRating(int rating)
    {
        selectedRating = rating;
        RecipeService.AddRating(RecipeId, rating);
        submitted = true;
    }
}
```

